// Check if key already exists
if (ckh_search(ckh, key, NULL, NULL) == false) {
    return false; // Key already exists, no insertion needed
}

size_t hashes[2];
ckh->hash(key, hashes);

// Try to insert in primary bucket
size_t bucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
    return false; // Successfully inserted
}

// Try to insert in secondary bucket
bucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);
if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
    return false; // Successfully inserted
}

// Both buckets are full, need cuckoo eviction
const void *evicted_key = key;
const void *evicted_data = data;
size_t start_bucket = bucket;

while (true) {
    // Choose random cell to evict
    unsigned i = (unsigned)prng_lg_range_u64(&ckh->prng_state, LG_CKH_BUCKET_CELLS);
    ckhc_t *cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + i];

    // Swap with evicted item
    const void *temp_key = cell->key;
    const void *temp_data = cell->data;
    cell->key = evicted_key;
    cell->data = evicted_data;
    evicted_key = temp_key;
    evicted_data = temp_data;

    // Find the alternate bucket for the evicted item
    ckh->hash(evicted_key, hashes);
    size_t new_bucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    if (new_bucket == bucket) {
        new_bucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    }

    // Check for cycle - if we're back to start bucket, need to grow
    if (new_bucket == start_bucket) {
        return true; // Need to grow table
    }

    bucket = new_bucket;

    // Try to insert in new bucket
    if (!ckh_try_bucket_insert(ckh, bucket, evicted_key, evicted_data)) {
        return false; // Successfully inserted after eviction
    }

    // Bucket is full, continue eviction process
}
